  1	import { db } from "../lib/db";
  2	import { SANDBOX } from "../lib/sandbox";
  3	import type { Job } from "@prisma/client";
  4	import { runRealMigration, migrationWorkDir, type MigrationStepResult, type ScanSnapshot } from "./migrate-real";
  5	
  6	/**
  7	 * Real cross-provider transfer is OFF by default. It only runs when the operator
  8	 * explicitly sets ENABLE_REAL_MIGRATION=1 (and never in the sandbox). Otherwise
  9	 * the safe, progress-reporting SIMULATION below runs. The real engine
 10	 * (worker/migrate-real.ts) is hardened against shell injection and never lets a
 11	 * secret touch a command string. Enable it only after testing on a throwaway VM.
 12	 */
 13	const REAL_MIGRATION = process.env.ENABLE_REAL_MIGRATION === "1" && !SANDBOX;
 14	
 15	/**
 16	 * MIGRATE — pull a customer's files + databases from another provider's VPS onto
 17	 * their new Nxeon server.
 18	 *
 19	 * `worker/index.ts` owns the job loop and the `handlers` map; wire this in there:
 20	 *   MIGRATE: runMigration,
 21	 *
 22	 * Ownership + validation happen at enqueue time (lib/actions-migrate.ts), so the
 23	 * handler trusts `payload.migrationId`.
 24	 *
 25	 * SAFETY: real cross-provider transfer (SSH into the source, rsync-pull files,
 26	 * mysqldump/pg_dump → import on target) is involved infra that has to be built
 27	 * out carefully — see the TODO(real migration) block below. For now this runs a
 28	 * SANDBOX-SAFE SIMULATION that walks realistic stages and reports progress, so
 29	 * it is harmless to run against real infrastructure. It NEVER opens a real SSH
 30	 * connection to the customer's source box.
 31	 *
 32	 * On completion (DONE or FAILED) every stored source secret is CLEARED:
 33	 * `sourcePasswordEnc` and each database's `passEnc`. A finished Migration row
 34	 * therefore never retains usable credentials.
 35	 */
 36	
 37	type MigratePayload = { migrationId?: string };
 38	type MigrationItems = {
 39	  paths?: string[];
 40	  // Legacy per-DB list (with encrypted password) — kept optional for old rows.
 41	  databases?: { engine: string; name: string; user: string; passEnc?: string }[];
 42	  // Passwordless lift-and-shift plan (extended TS shape carried through the
 43	  // existing Migration.items Json column — no schema change).
 44	  dbEngines?: string[];
 45	  dockerVolumes?: string[];
 46	  composeDirs?: string[];
 47	  verifyPorts?: number[];
 48	  hasContainers?: boolean;
 49	  webServers?: string[];
 50	  runtimes?: string[];
 51	  scan?: ScanSnapshot;
 52	  // Written back at completion: the honest per-step outcome summary.
 53	  results?: MigrationStepResult[];
 54	};
 55	
 56	const MAX_LOG_CHARS = 8000;
 57	
 58	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
 59	
 60	/** Append a timestamped line to a log tail, keeping it bounded. */
 61	function appendLog(prev: string | null | undefined, line: string): string {
 62	  const stamp = new Date().toISOString().slice(11, 19);
 63	  const next = `${prev ?? ""}${prev ? "\n" : ""}[${stamp}] ${line}`;
 64	  return next.length > MAX_LOG_CHARS ? next.slice(next.length - MAX_LOG_CHARS) : next;
 65	}
 66	
 67	async function loadMigration(job: Job) {
 68	  const payload = (job.payload ?? {}) as MigratePayload;
 69	  if (!payload.migrationId) throw new Error("migrate job: missing migrationId");
 70	  const migration = await db.migration.findUnique({ where: { id: payload.migrationId } });
 71	  if (!migration) throw new Error(`Migration ${payload.migrationId} not found`);
 72	  // Migration has no Prisma relation to Server (serverId is a plain FK) — resolve
 73	  // the target server row separately. `dedicatedIp` is needed by the real engine
 74	  // to compute the SSH connection target.
 75	  const server = await db.server.findUnique({
 76	    where: { id: migration.serverId },
 77	    include: { dedicatedIp: true },
 78	  });
 79	  return { ...migration, server };
 80	}
 81	
 82	/**
 83	 * Strip every source secret from a migration row. Called once the job finishes
 84	 * (success or failure) so a completed migration never keeps usable credentials.
 85	 */
 86	async function clearSecrets(
 87	  migrationId: string,
 88	  items: MigrationItems,
 89	  results?: MigrationStepResult[]
 90	) {
 91	  // Preserve every NON-secret field (so the wizard/summary keep working) while
 92	  // stripping the only secret carried in items — each legacy DB's passEnc. The
 93	  // source SSH password (sourcePasswordEnc column) is nulled separately.
 94	  const scrubbed: MigrationItems = {
 95	    ...items,
 96	    databases: (items.databases ?? []).map((d) => ({
 97	      engine: d.engine,
 98	      name: d.name,
 99	      user: d.user,
100	      // passEnc dropped entirely
101	    })),
102	    ...(results ? { results } : {}),
103	  };
104	  await db.migration.update({
105	    where: { id: migrationId },
106	    data: { sourcePasswordEnc: null, items: scrubbed as any },
107	  });
108	}
109	
110	async function report(
111	  migrationId: string,
112	  progress: number,
113	  step: string,
114	  logLine: string,
115	  logTail: string | null
116	): Promise<string> {
117	  const log = appendLog(logTail, logLine);
118	  await db.migration.update({
119	    where: { id: migrationId },
120	    data: { status: "RUNNING", progress, step, log },
121	  });
122	  return log;
123	}
124	
125	async function notify(userId: string, title: string, body?: string, href?: string) {
126	  try {
127	    await db.notification.create({ data: { userId, title, body, href } });
128	  } catch (e) {
129	    console.error("[migrate] notify failed", e);
130	  }
131	}
132	
133	export async function runMigration(job: Job): Promise<void> {
134	  const migration = await loadMigration(job);
135	  const items = (migration.items ?? {}) as MigrationItems;
136	  const paths = items.paths ?? [];
137	  const target = migration.server;
138	  const targetName = target ? target.label || target.hostname : "your server";
139	
140	  // Fresh start (also lets a retried job re-enter cleanly).
141	  let log = appendLog(null, `Starting migration from ${migration.sourceUser}@${migration.sourceHost}:${migration.sourcePort} → ${targetName}`);
142	  await db.migration.update({
143	    where: { id: migration.id },
144	    data: { status: "RUNNING", progress: 5, step: "Starting", log, lastError: null, finishedAt: null },
145	  });
146	
147	  // Shared progress reporter: threads the bounded log tail through each update so
148	  // both the real engine and the simulation write to the same Migration row.
149	  const reportStep = async (progress: number, step: string, line: string) => {
150	    log = await report(migration.id, progress, step, line, log);
151	  };
152	
153	  try {
154	    if (REAL_MIGRATION) {
155	      // ---- REAL lift-and-shift (hardened; opt-in via ENABLE_REAL_MIGRATION) --
156	      const summary = await runRealMigration({
157	        migration: {
158	          id: migration.id,
159	          sourceHost: migration.sourceHost,
160	          sourcePort: migration.sourcePort,
161	          sourceUser: migration.sourceUser,
162	          sourcePasswordEnc: migration.sourcePasswordEnc,
163	        },
164	        target: target as any,
165	        items,
166	        report: reportStep,
167	      });
168	
169	      // The engine returns an HONEST outcome. A run that executed every step but
170	      // left a source domain dark — or a migrated unit crash-looping — is NOT a
171	      // success, and must never be written back as one.
172	      //
173	      // This line is why the 2026-07-25 migration reported "Completed" while the
174	      // customer's site served a certificate warning and then Apache's default
175	      // page: the status was hardcoded, so no amount of verification downstream
176	      // could change what the customer was told. `COMPLETED_WITH_ISSUES` is
177	      // terminal (MigrationWizard treats it as an end state) but visibly distinct.
178	      const clean = summary.outcome === "COMPLETED";
179	      const unserved = summary.unservedDomains ?? [];
180	      await db.migration.update({
181	        where: { id: migration.id },
182	        data: {
183	          status: clean ? "DONE" : "COMPLETED_WITH_ISSUES",
184	          progress: 100,
185	          step: clean ? "Completed" : "Finished — some sites need attention",
186	          finishedAt: new Date(),
187	        },
188	      });
189	      // Persist the honest step-by-step summary (secret-free) into items.results.
190	      await clearSecrets(migration.id, items, summary.results);
191	
192	      const workDir = migrationWorkDir(migration.id);
193	      const running = summary.verifiedRunning.length;
194	      const manual = summary.needsAttention.length;
195	      const tail =
196	        `Any DB dumps that couldn't import were kept under ${workDir}/dumps. ` +
197	        `Your old server is untouched — if anything looks wrong, point DNS back to it while we sort this out.`;
198	      // Lead with the bad news when there is bad news. Burying dark domains under
199	      // a "completed" headline is what cost the customer a working site.
200	      const body = clean
201	        ? `Lift-and-shift onto ${targetName} finished. ${running} item(s) migrated & verified running; ` +
202	          `${manual} copied that may need a manual step. ` +
203	          (manual ? `To finish: ${summary.needsAttention.slice(0, 5).join(" | ")}${manual > 5 ? " …" : ""}. ` : "") +
204	          tail
205	        : `Lift-and-shift onto ${targetName} finished, but it is NOT fully live yet. ` +
206	          (unserved.length
207	            ? `These site(s) are not serving on the new server: ${unserved.slice(0, 8).join(", ")}${unserved.length > 8 ? ` (+${unserved.length - 8} more)` : ""}. `
208	            : "") +
209	          `${(summary.outcomeReasons ?? []).join("; ")}. ` +
210	          `${running} item(s) verified running. ` +
211	          tail;
212	      await notify(
213	        migration.userId,
214	        clean
215	          ? `Migration to ${targetName} completed`
216	          : `Migration to ${targetName} finished — ${unserved.length || "some"} site(s) need attention`,
217	        body,
218	        "/dashboard/migrate"
219	      );
220	      return;
221	    }
222	
223	    // ---- Progress-reporting SIMULATION of the lift-and-shift (default) --------
224	    // Mirrors the real engine's flow (dump DBs via root, install prerequisites,
225	    // import DBs, compose up, verify) with SYNTHETIC success. Delays are short so
226	    // the UI polls a live-feeling progression. NEVER opens a real SSH connection.
227	    const dbEngines = (items.dbEngines ?? []).filter((e) => e === "mysql" || e === "postgres");
228	    const composeDirs = items.composeDirs ?? [];
229	    const webServers = items.webServers ?? [];
230	    const runtimes = items.runtimes ?? [];
231	    const verifyPorts = items.verifyPorts ?? [];
232	    const hasContainers = !!items.hasContainers || composeDirs.length > 0;
233	    const simResults: MigrationStepResult[] = [];
234	
235	    await reportStep(6, "Connecting…", `Connecting to your Nxeon server (${targetName}) to prepare the lift-and-shift.`);
236	    await sleep(SANDBOX ? 500 : 1000);
237	    await reportStep(12, "Connecting to source…", `Connecting to ${migration.sourceHost} over SSH (port ${migration.sourcePort}). Authenticated with root.`);
238	    await sleep(SANDBOX ? 400 : 800);
239	
240	    // Prerequisites stage.
241	    const prereqLabels: string[] = [];
242	    if (dbEngines.includes("mysql")) prereqLabels.push("MySQL/MariaDB server");
243	    if (dbEngines.includes("postgres")) prereqLabels.push("PostgreSQL server");
244	    if (hasContainers) prereqLabels.push("Docker Engine + compose");
245	    for (const w of webServers) prereqLabels.push(w === "nginx" ? "nginx" : "Apache");
246	    for (const rt of runtimes) prereqLabels.push(rt === "nodejs" ? "Node.js" : "Python 3 + pip");
247	    if (prereqLabels.length) {
248	      await reportStep(18, "Installing prerequisites…", `Installing on ${targetName}: ${prereqLabels.join(", ")}.`);
249	      for (const lbl of prereqLabels) {
250	        await sleep(SANDBOX ? 200 : 400);
251	        await reportStep(20, "Installing prerequisites…", `  ${lbl}: installed.`);
252	        simResults.push({ step: `Install ${lbl}`, status: "running", detail: "installed" });
253	      }
254	    }
255	
256	    // Files stage — same-path copy.
257	    await reportStep(30, "Copying files…", paths.length ? `Copying ${paths.length} path(s) to the same locations on ${targetName}.` : "No file paths selected — skipping file copy.");
258	    for (const p of paths) {
259	      await sleep(SANDBOX ? 200 : 400);
260	      await reportStep(40, "Copying files…", `  rsync ${p} → ${p}`);
261	    }
262	    if (paths.length) simResults.push({ step: `Copy ${paths.length} folder(s) to their original paths`, status: "copied", detail: "files placed at the same paths" });
263	
264	    // Databases — dump via source root LOCAL auth (no password), import on target.
265	    for (const eng of dbEngines) {
266	      await sleep(SANDBOX ? 300 : 600);
267	      if (eng === "mysql") {
268	        await reportStep(62, "Migrating databases…", "  mysqldump --all-databases via source root socket (no password) → mysql < dump on target.");
269	        simResults.push({ step: "Migrate MySQL/MariaDB databases", status: "copied", detail: "dumped via source root socket and imported" });
270	      } else {
271	        await reportStep(64, "Migrating databases…", "  sudo -u postgres pg_dumpall via peer auth → psql -f on target.");
272	        simResults.push({ step: "Migrate PostgreSQL databases", status: "copied", detail: "dumped via source postgres peer auth and imported" });
273	      }
274	    }
275	
276	    // Docker compose bring-up.
277	    for (const dir of composeDirs) {
278	      await sleep(SANDBOX ? 250 : 500);
279	      await reportStep(76, "Starting containers…", `  cd ${dir} && docker compose up -d`);
280	      simResults.push({ step: `Compose up ${dir}`, status: "running", detail: "docker compose up -d succeeded" });
281	    }
282	
283	    // Verification.
284	    await reportStep(92, "Verifying…", "Checking databases, containers and listening ports on the new server.");
285	    await sleep(SANDBOX ? 400 : 800);
286	    if (dbEngines.includes("mysql")) simResults.push({ step: "MySQL/MariaDB engine", status: "running", detail: "engine is active on the target" });
287	    if (dbEngines.includes("postgres")) simResults.push({ step: "PostgreSQL engine", status: "running", detail: "engine is active on the target" });
288	    if (hasContainers) {
289	      await reportStep(94, "Verifying…", `  docker ps shows ${composeDirs.length || 1} running container(s).`);
290	      simResults.push({ step: "Docker containers", status: "running", detail: `${composeDirs.length || 1} container(s) running` });
291	    }
292	    if (verifyPorts.length) {
293	      await reportStep(95, "Verifying…", `  ports up: ${verifyPorts.join(", ")}.`);
294	      simResults.push({ step: "Listening ports", status: "running", detail: `now listening: ${verifyPorts.join(", ")}` });
295	    }
296	
297	    const simRunning = simResults.filter((r) => r.status === "running").length;
298	    const simManual = simResults.filter((r) => r.status === "copied" || r.status === "failed").length;
299	    await reportStep(98, "Finalising…", `Migrated & running (verified): ${simRunning}. Copied — may need a manual step: ${simManual}.`);
300	    await sleep(SANDBOX ? 300 : 600);
301	
302	    await db.migration.update({
303	      where: { id: migration.id },
304	      data: { status: "DONE", progress: 100, step: "Completed", finishedAt: new Date() },
305	    });
306	    // Security: drop all source credentials now that the job is done; persist summary.
307	    await clearSecrets(migration.id, items, simResults);
308	
309	    await notify(
310	      migration.userId,
311	      `Migration to ${targetName} completed`,
312	      `Lift-and-shift onto ${targetName} finished: ${simRunning} item(s) migrated & running, ${simManual} copied. Point your DNS at the new server when ready.`,
313	      "/dashboard/migrate"
314	    );
315	  } catch (e: any) {
316	    const lastError = `${e?.message ?? e}`.slice(0, 1000);
317	    console.error(`[migrate] migration ${migration.id} failed:`, e);
318	    log = appendLog(log, `ERROR: ${lastError}`);
319	    await db.migration
320	      .update({
321	        where: { id: migration.id },
322	        data: { status: "FAILED", step: "Failed", lastError, log, finishedAt: new Date() },
323	      })
324	      .catch(() => {});
325	    // Security: clear the stored source password/DB secrets even on failure.
326	    await clearSecrets(migration.id, items).catch(() => {});
327	    await notify(
328	      migration.userId,
329	      `Migration to ${targetName} failed`,
330	      lastError,
331	      "/dashboard/migrate"
332	    );
333	    // Swallow — the failure is recorded on the Migration row. Re-throwing would
334	    // make the job loop retry a migration whose secrets we've already cleared.
335	  }
336	}

