149: function Stepper({ step }: { step: number }) {
150:   return (
151:     <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
152:       {STEPS.map((s, i) => (
153:         <div key={s} className="flex items-center gap-2">
154:           <span
155:             className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
156:               i === step
157:                 ? "border-brand-400 bg-brand-500/20 text-brand-200"
158:                 : i < step
159:                   ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
160:                   : "border-white/10 text-slate-500"
161:             }`}
162:           >
163:             {i < step ? "✓" : i + 1}
164:           </span>
165:           <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
166:           {i < STEPS.length - 1 && <span className="mx-1 text-slate-700">→</span>}
167:         </div>
168:       ))}
169:     </div>
170:   );
171: }
