222: export function MigrationWizard({
223:   servers,
224:   osTemplates = [],
225: }: {
226:   servers: ServerOption[];
227:   osTemplates?: OsTemplateOption[];
228: }) {
229:   const [step, setStep] = useState(0);
230:   const [error, setError] = useState<string | null>(null);
231:   const [scanning, setScanning] = useState(false);
232:   const [submitting, setSubmitting] = useState(false);
233:   const [activeId, setActiveId] = useState<string | null>(null);
234: 
235:   // Step 0 — destination
236:   const [serverId, setServerId] = useState(servers[0]?.id ?? "");
237:   // Step 1 — source
238:   const [host, setHost] = useState("");
239:   const [port, setPort] = useState("22");
240:   const [user, setUser] = useState("root");
241:   const [password, setPassword] = useState("");
242: 
243:   // Step 2 — detection results + selections
244:   const [scan, setScan] = useState<ScanResult | null>(null);
245:   // Target free-space + OS/arch probe (for storage & compatibility guardrails).
246:   // undefined = not yet fetched; a value with disk:null = probe failed (soft warn).
247:   const [targetInfo, setTargetInfo] = useState<TargetInfo | null | undefined>(undefined);
248:   const [webSel, setWebSel] = useState<Set<string>>(new Set());
249:   const [homeSel, setHomeSel] = useState<Set<string>>(new Set());
250:   const [appSel, setAppSel] = useState<Set<string>>(new Set());
251:   const [dockerSel, setDockerSel] = useState<Set<string>>(new Set());
252:   const [customPaths, setCustomPaths] = useState<string[]>([]);
253:   const [newPath, setNewPath] = useState("");
254:   // Explicit opt-in to spend an attached block-storage volume on Docker's data.
255:   // OFF by default and never flipped on automatically: while a volume holds
256:   // /var/lib/docker the server can't run without it, so it stops being the
257:   // portable, move-it-to-another-server add-on the Volumes page promises.
258:   const [useVolumeForDocker, setUseVolumeForDocker] = useState(false);
259: 
260:   // Deep-link back into a migration's result view (?migration=<id>). Used when a
261:   // customer leaves for Cloudflare's consent screen from the completed-migration
262:   // panel — they come back to exactly where they were, not to a blank wizard.
263:   useEffect(() => {
264:     const id = new URLSearchParams(window.location.search).get("migration");
265:     if (id && /^[A-Za-z0-9_-]{6,64}$/.test(id)) setActiveId(id);
266:   }, []);
267: 
268:   const hostValid = /^[a-zA-Z0-9.\-:[\]]+$/.test(host.trim()) && host.trim().length > 0;
269:   const portNum = Number(port);
270:   const portValid = Number.isInteger(portNum) && portNum >= 1 && portNum <= 65535;
271:   const canScan = hostValid && portValid && user.trim().length > 0 && password.length > 0;
272: 
273:   async function runScan() {
274:     setError(null);
275:     setScanning(true);
276:     setTargetInfo(undefined);
277:     try {
278:       // Scan the source and probe the destination's free space in parallel.
279:       const [res, diskRes] = await Promise.all([
280:         scanSource({
281:           serverId,
282:           sourceHost: host.trim(),
283:           sourcePort: portNum,
284:           sourceUser: user.trim(),
285:           sourcePassword: password,
286:         }),
287:         targetDiskFree(serverId).catch(() => ({ info: undefined })),
288:       ]);
289:       if (res.error) {
290:         setError(res.error);
291:         return;
292:       }
293:       setTargetInfo(diskRes?.info ?? null);
294:       const s = res.scan!;
295:       setScan(s);
296:       // Pre-check everything we found — the customer just unchecks what they don't want.
297:       setWebSel(new Set(s.webRoots.map((w) => w.path)));
298:       setHomeSel(new Set(s.homes.map((h) => h.path)));
299:       setAppSel(new Set(s.appDirs.map((a) => a.path)));
300:       // Docker bind-mount host paths are the container's data — pre-check the copyable ones.
