364:   // ---- Storage guardrail — total to migrate vs. target free space ----------
365:   // Recomputes live as the customer checks/unchecks. Unknown-size items (custom
366:   // folders, Docker mounts) contribute 0; the DB estimate is added whenever an
367:   // engine is detected (databases are auto-included).
368:   /**
369:    * The move splits across two destinations, so we size them separately:
370:    *  - `fileBytes`   → the selected folders + databases, restored to their original
371:    *                    paths, i.e. onto the ROOT filesystem.
372:    *  - `dockerBytes` → Docker images (they unpack to roughly 2x while loading) plus
373:    *                    working headroom, which live under /var/lib/{docker,containerd}
374:    *                    — the engine relocates those onto an unused volume, but
375:    *                    ONLY if the customer opts in to using it.
376:    * Nothing ever needs `fileBytes + dockerBytes` contiguously, so testing the
377:    * combined total against a single disk understates what actually fits.
378:    */
379:   const { fileBytes, dockerBytes, totalBytes } = useMemo(() => {
380:     if (!scan) return { fileBytes: 0, dockerBytes: 0, totalBytes: 0 };
381:     const byPath = new Map<string, number>();
382:     scan.webRoots.forEach((w) => byPath.set(w.path, parseSize(w.sizeLabel)));
383:     scan.homes.forEach((h) => byPath.set(h.path, parseSize(h.sizeLabel)));
384:     scan.appDirs.forEach((a) => byPath.set(a.path, parseSize(a.sizeLabel)));
385:     let f = 0;
386:     for (const p of selectedPaths) f += byPath.get(p) ?? 0;
387:     if (detectedEngines.length > 0) f += Math.max(0, scan.dbSizeBytes ?? 0);
388:     const imageBytes = Math.max(0, scan.dockerImageBytes ?? 0);
389:     const d = imageBytes > 0 ? imageBytes * 2 + 2 * GiB : 0;
390:     return { fileBytes: f, dockerBytes: d, totalBytes: f + d };
391:   }, [scan, selectedPaths, detectedEngines]);
