103: // ---- Validation -------------------------------------------------------------
104: 
105: // Hostname/FQDN (RFC-1123-ish) or IPv4 literal. Deliberately permissive on IPv6
106: // (a bracketed/colon form is accepted) — the worker's SSH layer does the final
107: // resolution; this only rejects obvious junk before we store anything.
108: const HOST_RE =
109:   /^(?:(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)*[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?|\d{1,3}(?:\.\d{1,3}){3}|\[?[0-9a-fA-F:]+\]?)$/;
110: const DEFAULT_PATHS = ["/var/www", "/home"];
111: const MAX_PATHS = 40;
112: 
113: function cleanPaths(paths: string[] | undefined): string[] {
114:   const list = (paths && paths.length ? paths : DEFAULT_PATHS)
115:     .map((p) => p.trim())
116:     .filter((p) => p.length > 0 && p.startsWith("/") && !p.includes("\0"));
117:   // De-dupe while preserving order.
118:   return [...new Set(list)].slice(0, MAX_PATHS);
119: }
120: 
121: // Docker volume names are shell-inert (docker's own charset) — the worker
122: // re-validates, but we only ever store well-formed names.
123: const VOLNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
124: function isCopyableAbsPath(p: string): boolean {
125:   return typeof p === "string" && p.startsWith("/") && !p.includes("..") && p.length > 1;
126: }
127: 
128: /**
129:  * Derive the passwordless lift-and-shift plan from the read-only scan and the set
130:  * of paths the customer chose to copy. Databases are auto-included whenever an
131:  * engine was detected (no password needed — the worker dumps via root's local
132:  * socket/peer auth); Docker/web/runtime prerequisites are inferred so the worker
133:  * can install them on the target. Everything here is secret-free.
134:  */
135: function derivePlan(scan: ScanResult | undefined, selectedPaths: string[]): MigrationPlan {
136:   const empty: MigrationPlan = {
137:     dbEngines: [],
138:     dockerVolumes: [],
139:     composeDirs: [],
140:     verifyPorts: [],
141:     hasContainers: false,
142:     webServers: [],
143:     runtimes: [],
144:   };
145:   if (!scan || !scan.ok) return empty;
146:   const pathSet = new Set(selectedPaths);
147: 
148:   // Auto-include every detected engine (dump passwordlessly via root local auth).
149:   const dbEngines = [...new Set((scan.engines ?? []).filter((e) => e.present).map((e) => e.engine))].filter(
150:     (e): e is "mysql" | "postgres" => e === "mysql" || e === "postgres"
151:   );
152: 
153:   const containers = scan.containers ?? [];
154:   // Named Docker volumes = container mounts that are NOT absolute host paths.
155:   const dockerVolumes = [
156:     ...new Set(
157:       containers.flatMap((c) => c.mounts ?? []).filter((m) => !isCopyableAbsPath(m) && VOLNAME_RE.test(m))
158:     ),
159:   ].slice(0, 60);
160: 
161:   // Compose project dirs among the app dirs the customer is actually copying.
162:   const composeDirs = [
163:     ...new Set((scan.appDirs ?? []).filter((a) => a.signature === "compose" && pathSet.has(a.path)).map((a) => a.path)),
164:   ].slice(0, 40);
165: 
166:   const verifyPorts = [
167:     ...new Set((scan.ports ?? []).map((p) => p.port).filter((p) => Number.isInteger(p) && p >= 1 && p <= 65535 && p !== 22)),
168:   ].slice(0, 60);
169: 
170:   const hasContainers = containers.length > 0 || composeDirs.length > 0 || dockerVolumes.length > 0;
171: 
172:   // Web servers: match the owning process/service names, else default to nginx
173:   // when web roots exist (the overwhelmingly common case).
174:   const procBlob = [
175:     ...(scan.ports ?? []).map((p) => p.proc || ""),
176:     ...(scan.services ?? []).map((s) => s.name || ""),
177:   ]
178:     .join(" ")
179:     .toLowerCase();
180:   const webServers: ("nginx" | "apache")[] = [];
181:   if (/nginx/.test(procBlob)) webServers.push("nginx");
182:   if (/apache|httpd/.test(procBlob)) webServers.push("apache");
183:   if (webServers.length === 0 && (scan.webRoots ?? []).length > 0) webServers.push("nginx");
184: 
185:   // Runtimes: from running-app runtimes and listening-port owners. Conservative.
186:   const runtimeBlob = [
187:     ...(scan.appDirs ?? []).map((a) => a.runtime || ""),
188:     ...(scan.ports ?? []).map((p) => p.proc || ""),
189:   ]
190:     .join(" ")
191:     .toLowerCase();
192:   const runtimes: ("nodejs" | "python3")[] = [];
193:   if (/node|next|pm2/.test(runtimeBlob)) runtimes.push("nodejs");
194:   if (/python|gunicorn|uvicorn|celery/.test(runtimeBlob)) runtimes.push("python3");
195: 
196:   return { dbEngines, dockerVolumes, composeDirs, verifyPorts, hasContainers, webServers, runtimes };
197: }
198: 
199: const GiB = 1024 ** 3;
200: 
201: /** Working headroom the transfer needs while images load/unpack. Mirrors the
202:  *  engine's pre-flight allowance in worker/migrate-real.ts so the wizard's
203:  *  "will it fit?" answer and the worker's refusal can never disagree. */
204: const MIGRATION_HEADROOM_BYTES = 2 * GiB;
205: void MIGRATION_HEADROOM_BYTES; // kept for reference; the worker owns the headroom allowance
206: 
207: /**
208:  * Sum (in bytes) of the SELECTED migration items, plus the DB data-dir estimate
209:  * when a database engine was detected (databases are auto-included). Sizes come
210:  * from the read-only scan's human size labels; unknown-size items (custom folders,
211:  * Docker mounts) count as 0. Used both for the client storage panel and the
212:  * worker pre-flight — computed server-side here so the stored total is trusted.
213:  */
214: function selectedMigrationBytes(scan: ScanResult | undefined, selectedPaths: string[]): number {
215:   if (!scan || !scan.ok) return 0;
216:   const sizeByPath = new Map<string, number>();
217:   for (const w of scan.webRoots ?? []) sizeByPath.set(w.path, parseSizeLabel(w.sizeLabel));
218:   for (const h of scan.homes ?? []) sizeByPath.set(h.path, parseSizeLabel(h.sizeLabel));
219:   for (const a of scan.appDirs ?? []) sizeByPath.set(a.path, parseSizeLabel(a.sizeLabel));
220:   let total = 0;
221:   for (const p of selectedPaths) total += sizeByPath.get(p) ?? 0;
222:   // Databases are auto-included whenever an engine is present.
223:   const enginePresent = (scan.engines ?? []).some((e) => e.present);
224:   if (enginePresent) total += Math.max(0, scan.dbSizeBytes ?? 0);
225:   // CONTRACT — this is FILES ONLY (selected paths + the DB data-dir estimate).
226:   // It is stored as `items.totalBytes`, and the worker pre-flight reads it as
227:   // `fileBytes` and then adds the Docker image allowance + headroom ITSELF
228:   // (worker/migrate-real.ts). Adding Docker here as well made the engine count it
229:   // TWICE — a ~12 GB move was reported as needing 83.6 GB and refused. The wizard
230:   // displays the combined figure by computing its own file/Docker split
231:   // client-side; it never renders this value, so keep this files-only.
232:   return Math.round(total);
233: }
234: 
235: /** Parse ID / VERSION_ID / PRETTY_NAME lines from `/etc/os-release` (never sourced). */
236: function parseOsRelease(stdout: string): { id: string; versionId: string; pretty: string } | null {
237:   const o: Record<string, string> = {};
238:   for (const line of (stdout ?? "").split("\n")) {
239:     const m = /^(ID|VERSION_ID|PRETTY_NAME)=(.*)$/.exec(line.trim());
240:     if (!m) continue;
241:     o[m[1]] = m[2].trim().replace(/^["']|["']$/g, "").slice(0, 128);
242:   }
243:   if (!o.ID && !o.PRETTY_NAME && !o.VERSION_ID) return null;
244:   return {
245:     id: (o.ID ?? "").toLowerCase().slice(0, 32),
246:     versionId: (o.VERSION_ID ?? "").slice(0, 32),
247:     pretty: o.PRETTY_NAME ?? "",
248:   };
249: }
