706: // ---- Post-migration DNS cutover --------------------------------------------
707: 
708: /**
709:  * A domain we can offer to repoint after a migration, plus where we got it from
710:  * (shown in the UI so the customer knows why it's listed).
711:  */
712: export type DnsCandidate = {
713:   host: string;
714:   source: "registered" | "website" | "scan";
715: };
716: 
717: export type MigrationDnsInfo = {
718:   error?: string;
719:   targetIp?: string | null;
720:   targetName?: string | null;
721:   candidates?: DnsCandidate[];
722:   cloudflareConnected?: boolean;
723: };
724: 
725: /** Pull a hostname out of a path like `/var/www/example.com` / `/home/example.com`. */
726: function hostnameFromPath(path: string): string | null {
727:   const leaf = String(path ?? "").split("/").filter(Boolean).pop() ?? "";
728:   const h = leaf.toLowerCase().replace(/^www\./, "");
729:   return cleanHostname(h);
730: }
731: 
732: /**
733:  * Candidate domains to point at the migration's target server, cheapest source
734:  * first. Ownership-checked (the migration must be the caller's).
735:  *
736:  *   1. `Domain` rows — domains the customer registered with us.
737:  *   2. Websites already configured on the target server.
738:  *   3. Hostnames inferable from the STORED scan snapshot (`Migration.items.scan`)
739:  *      — web-root folders are conventionally named after the vhost. The snapshot
740:  *      does not record nginx/apache `server_name` values, so this is a best-effort
741:  *      read of what was already captured; we never re-scan the source.
742:  */
743: export async function getMigrationDnsInfo(migrationId: string): Promise<MigrationDnsInfo> {
744:   const user = await requireUser();
745: 
746:   const m = await db.migration.findUnique({ where: { id: migrationId } });
747:   if (!m) return { error: "Migration not found." };
748:   if (m.userId !== user.id && user.role !== "ADMIN") return { error: "Not your migration." };
749: 
750:   const server = await db.server.findUnique({
751:     where: { id: m.serverId },
752:     select: { hostname: true, label: true, ipAddress: true, dedicatedIp: { select: { address: true } } },
753:   });
754: 
755:   const seen = new Set<string>();
756:   const candidates: DnsCandidate[] = [];
757:   const push = (raw: string | null | undefined, source: DnsCandidate["source"]) => {
758:     const host = cleanHostname(raw ?? "");
759:     if (!host || seen.has(host)) return;
760:     seen.add(host);
761:     candidates.push({ host, source });
762:   };
763: 
764:   const domains = await db.domain.findMany({
765:     where: { userId: m.userId },
766:     select: { name: true },
767:     orderBy: { name: "asc" },
768:     take: 50,
769:   });
770:   for (const d of domains) push(d.name, "registered");
771: 
772:   const sites = await db.website.findMany({
773:     where: { serverId: m.serverId },
774:     select: { domain: true },
775:     take: 50,
776:   });
777:   for (const s of sites) push(s.domain, "website");
778: 
779:   // Only what the scan already stored — no new source-scanning here.
780:   const items = (m.items ?? {}) as { scan?: { webRoots?: { path?: string }[] } };
781:   for (const w of items.scan?.webRoots ?? []) {
782:     if (w?.path) push(hostnameFromPath(w.path), "scan");
783:   }
784: 
785:   return {
786:     targetIp: server?.dedicatedIp?.address ?? server?.ipAddress ?? null,
787:     targetName: server ? server.label || server.hostname : null,
788:     candidates: candidates.slice(0, 40),
789:     cloudflareConnected: readStoredCloudflare(user.cloudflareTokenEnc) !== null,
790:   };
791: }
792: 
793: /**
794:  * Point one hostname at the migration's TARGET server by upserting an A record in
795:  * the customer's Cloudflare zone — the last manual step of an otherwise one-click
796:  * migration.
797:  *
798:  * Guards: requireUser + migration ownership, rate-limited, and the hostname is
799:  * re-validated server-side (`cleanHostname` inside pointHostnameToIp) because
800:  * this one legitimately comes from customer input (the "enter a domain" box).
801:  * The record is DNS-only (proxied=false) so the name resolves to the server
802:  * itself and Let's Encrypt HTTP-01 validation can succeed there.
803:  */
804: export async function pointMigrationDns(
805:   migrationId: string,
806:   hostname: string
807: ): Promise<{ ok: true; message: string } | { ok: false; error: string }> {
808:   const user = await requireUser();
809: 
810:   const m = await db.migration.findUnique({ where: { id: migrationId } });
811:   if (!m) return { ok: false, error: "Migration not found." };
812:   if (m.userId !== user.id && user.role !== "ADMIN") return { ok: false, error: "Not your migration." };
813: 
814:   const rl = checkRateLimit(`migrate:dns:${user.id}`, { max: 20, windowMs: 60_000 });
815:   if (!rl.ok) return { ok: false, error: `Too many requests — retry in ${rl.retryAfterSec}s.` };
816: 
817:   const server = await db.server.findUnique({
818:     where: { id: m.serverId },
819:     select: { ipAddress: true, dedicatedIp: { select: { address: true } } },
820:   });
821:   const ip = server?.dedicatedIp?.address ?? server?.ipAddress ?? null;
822:   if (!ip) {
823:     return { ok: false, error: "Your new server doesn't have a public IP yet — try again shortly." };
824:   }
825: 
826:   const res = await pointHostnameToIp({
827:     user: { id: user.id, cloudflareTokenEnc: user.cloudflareTokenEnc },
828:     hostname,
829:     ip,
830:   });
831:   if (!res.ok) return { ok: false, error: res.error };
832: 
833:   await db.auditLog.create({
834:     data: {
835:       userId: user.id,
836:       action: "migration.dns",
837:       detail: `${res.hostname} A → ${ip}${res.simulated ? " (sandbox)" : ""}`,
838:     },
839:   });
840: 
841:   return {
842:     ok: true,
843:     message: res.simulated
844:       ? `Sandbox: pretended to point ${res.hostname} at ${ip} (DNS-only). Nothing was sent to Cloudflare.`
845:       : `${res.hostname} now points at ${ip} (A record ${res.action}, DNS-only). It can take a few minutes for visitors to see the new server.`,
846:   };
847: }

