3583:         const uidArg = (await shOk(conn, `getent passwd ${u.uid} >/dev/null 2>&1`)) ? "" : `-u ${u.uid} `;
3584:         const gidArg = (await shOk(conn, `getent group ${u.gid} >/dev/null 2>&1`)) ? `-g ${u.gid} ` : "";
