3599:       let idx = 0;
3600:       let copied = 0;
3601:       for (const p of paths) {
3602:         idx++;
3603:         const destParent = parentDir(p);
3604:         await execRemote(conn, `mkdir -p ${destParent}`, SETUP_TIMEOUT_MS);
3605:         const pct = 28 + Math.round((idx / paths.length) * 22); // 28 → 50
3606:         await report(pct, "Copying files…", `  rsync ${p} → ${p}`);
3607:         const r = await execRemote(conn, rsyncPull(p, destParent), TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
3608:         if (r.code === 0) {
3609:           copied++;
3610:         } else {
3611:           const tail = (r.stderr || r.stdout || "").split("\n").filter(Boolean).slice(-2).join(" ").slice(0, 200);
3612:           push({ step: `Copy ${p}`, status: "failed", detail: tail || `rsync exit ${r.code}` });
3613:           await report(pct, "Copying files…", `  copy failed for ${p}: ${tail || `rsync exit ${r.code}`}`);
