3655:     // ---- 8. Databases: dump via source root LOCAL auth, import on target ---
3656:     for (const engine of plan.dbEngines) {
3657:       await report(60, "Migrating databases…", `Dumping ${engine === "postgres" ? "PostgreSQL" : "MySQL/MariaDB"} from the source (root, no password).`);
3658:       if (engine === "mysql") {
3659:         const dump = `${work}/dumps/mysql-all.sql`;
3660:         // Dump ONLY the source's USER databases. `--all-databases` includes MySQL's
3661:         // internal system schemas (mysql, information_schema, performance_schema,
3662:         // sys); restoring the source's `mysql` schema into a different-version engine
3663:         // corrupts/aborts the import (ERROR 1728 "Cannot load from mysql.proc").
3664:         // So: enumerate databases over root's LOCAL socket auth (no password), drop
3665:         // the system schemas, and dump the rest by name.
3666:         const listCmd = `${priv}mysql -N -e "SHOW DATABASES"`;
3667:         const listed = await execRemote(conn, onSource(listCmd), SETUP_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
3668:         const SYSTEM_SCHEMAS = new Set(["mysql", "information_schema", "performance_schema", "sys"]);
3669:         const userDbs: string[] = [];
3670:         for (const raw of (listed.stdout || "").split("\n")) {
3671:           const name = raw.trim();
3672:           if (!name || SYSTEM_SCHEMAS.has(name.toLowerCase())) continue;
3673:           // Reject (never sanitize) any name that isn't a shell-inert identifier
3674:           // before it is interpolated into the dump command.
3675:           if (!IDENT_RE.test(name)) continue;
3676:           userDbs.push(name);
3677:         }
3678:         const dbList = [...new Set(userDbs)];
3679:         if (dbList.length === 0) {
3680:           if (listed.code !== 0) {
3681:             push({ step: "Migrate MySQL/MariaDB", status: "failed", detail: "root could not enumerate databases via local socket — import skipped" });
3682:             await report(62, "Migrating databases…", `  Could not list MySQL databases on the source — skipping.`);
3683:           } else {
3684:             push({ step: "Migrate MySQL/MariaDB", status: "skipped", detail: "no user databases to migrate (only system schemas present)" });
3685:             await report(62, "Migrating databases…", `  No user MySQL databases to migrate — skipped.`);
3686:           }
3687:           continue;
3688:         }
3689:         // mysqldump over root's LOCAL socket auth (Debian/Ubuntu root = auth_socket),
3690:         // limited to the validated user DB names.
3691:         const dumpCmd = `${priv}mysqldump --single-transaction --routines --triggers --events --databases ${dbList.join(" ")}`;
3692:         const r = await execRemote(conn, `${onSource(dumpCmd)} > ${dump} 2>${work}/dumps/mysql.err`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
3693:         const nonEmpty = await execRemote(conn, `test -s ${dump}`, SETUP_TIMEOUT_MS).then((x) => x.code === 0).catch(() => false);
3694:         if (r.code !== 0 || !nonEmpty) {
3695:           const err = await execRemote(conn, `tail -c 200 ${work}/dumps/mysql.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
3696:           push({ step: "Migrate MySQL/MariaDB", status: "failed", detail: `root could not dump via local socket${err ? `: ${err}` : ""} — import skipped` });
3697:           await report(62, "Migrating databases…", `  MySQL dump via root failed — skipping (databases left for manual export).`);
3698:         } else {
3699:           // Import on the target as its own root (socket auth — no password). `--force`
3700:           // keeps one bad statement from aborting the whole restore.

3700:           // keeps one bad statement from aborting the whole restore.
3701:           const imp = await execRemote(conn, `mysql --force < ${dump} 2>${work}/dumps/mysql-import.err`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
3702:           if (imp.code === 0) {
3703:             push({ step: "Migrate MySQL/MariaDB databases", status: "copied", detail: `dumped ${dbList.length} user database(s) via source root socket and imported on the target` });
3704:             await report(64, "Migrating databases…", `  MySQL databases dumped and imported (${dbList.length} user DB(s)).`);
3705:           } else {
3706:             const err = await execRemote(conn, `tail -c 200 ${work}/dumps/mysql-import.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
3707:             push({ step: "Import MySQL/MariaDB", status: "failed", detail: `dump succeeded but import failed${err ? `: ${err}` : ""} — dump kept at ${dump}` });
3708:           }
3709:         }
3710:       } else {
3711:         const dump = `${work}/dumps/postgres-all.sql`;
3712:         // pg_dumpall over peer auth as the postgres superuser.
3713:         const dumpCmd = user === "root" ? "sudo -u postgres pg_dumpall" : "sudo -n -u postgres pg_dumpall";
3714:         const r = await execRemote(conn, `${onSource(dumpCmd)} > ${dump} 2>${work}/dumps/pg.err`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
3715:         const nonEmpty = await execRemote(conn, `test -s ${dump}`, SETUP_TIMEOUT_MS).then((x) => x.code === 0).catch(() => false);
3716:         if (r.code !== 0 || !nonEmpty) {
3717:           const err = await execRemote(conn, `tail -c 200 ${work}/dumps/pg.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
3718:           push({ step: "Migrate PostgreSQL", status: "failed", detail: `postgres peer dump failed${err ? `: ${err}` : ""} — import skipped` });
