3720:         } else {
3721:           const imp = await execRemote(conn, `sudo -u postgres psql -f ${dump} >/dev/null 2>${work}/dumps/pg-import.err`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
