3729:               step: "Migrate PostgreSQL databases",
3730:               status: "copied",
3731:               detail: "dumped via source postgres peer auth and imported on the target, including database roles/logins and their passwords (pg_dumpall carries cluster globals)",
3732:             });
3733:             await report(64, "Migrating databases…", `  PostgreSQL databases, roles and logins dumped and imported.`);
