3735:             const err = await execRemote(conn, `tail -c 200 ${work}/dumps/pg-import.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
3736:             push({ step: "Import PostgreSQL", status: "failed", detail: `dump succeeded but import reported errors${err ? `: ${err}` : ""} — dump kept at ${dump}` });
