3742:     // ---- 8b. MySQL application accounts + grants --------------------------
3743:     // Silent app-breaker: the dump above intentionally skips the `mysql` system
3744:     // schema, so the DATA arrives but the accounts the apps log in as do not, and
3745:     // every connection fails with access-denied. Reproduce just the application
3746:     // accounts — never root or MySQL's own maintenance logins, which would
3747:     // overwrite the new server's own credentials.
3748:     //
3749:     // Password hashes never enter this process: the generator runs on the source
3750:     // and its output is redirected straight into a 0600 file on the target, which
3751:     // is applied and then shredded. Nothing from it is ever logged.
3752:     if (plan.dbEngines.includes("mysql") && inv.mysqlAccounts.length > 0) {
3753:       await report(66, "Migrating database users…", `Recreating ${inv.mysqlAccounts.length} application database account(s) with their existing passwords.`);
3754:       const usersSql = `${work}/dumps/mysql-users.sql`;
3755:       const genScript = await putScript(mysqlGrantsScript(priv, inv.mysqlAccounts));
3756:       const gen = await sh(conn, `(umask 077; ${onSourceScript(genScript)} > ${usersSql} 2>/dev/null)`, TRANSFER_TIMEOUT_MS);
3757:       const hasSql = await shOk(conn, `test -s ${usersSql}`);
3758:       if (gen.code !== 0 || !hasSql) {
3759:         push({
3760:           step: "Migrate database users",
3761:           status: "failed",
3762:           detail: `could not read the old server's database accounts — recreate ${inv.mysqlAccounts.length} MySQL user(s) and their grants by hand, or your apps will get access-denied`,
3763:         });
3764:       } else {
3765:         // --force: one unsupported statement (e.g. an auth plugin the target's
3766:         // engine lacks) must not abandon the remaining accounts.
3767:         const ap = await sh(conn, `mysql --force < ${usersSql} 2>${work}/dumps/mysql-users.err`, TRANSFER_TIMEOUT_MS);
3768:         // Confirm by ASKING THE TARGET which of the accounts now exist, rather
3769:         // than trusting an exit code.
3770:         const check = await sh(conn, `mysql -N -B -e "SELECT user, host FROM mysql.user" 2>/dev/null`);
3771:         const present = new Set(
3772:           clean(check.stdout, 8000)
3773:             .split("\n")
3774:             .map((l) => l.split(/\s+/).slice(0, 2).join("@"))
3775:         );
3776:         const landed = inv.mysqlAccounts.filter((a) => present.has(`${a.user}@${a.host}`));
3777:         const missing = inv.mysqlAccounts.filter((a) => !present.has(`${a.user}@${a.host}`));
3778:         // NEVER echo the error file — it can quote statements. Only count/classify.
3779:         const errCount = Number(
3780:           clean((await sh(conn, `grep -c '^ERROR' ${work}/dumps/mysql-users.err 2>/dev/null`)).stdout, 8)
3781:         ) || 0;
3782:         if (landed.length && !missing.length) {
3783:           push({
3784:             step: `Migrate ${landed.length} database user(s)`,
3785:             status: "running",
3786:             detail: "application database accounts and grants recreated with their existing passwords — apps can log in unchanged",
3787:           });
3788:           await report(67, "Migrating database users…", `  ${landed.length} database account(s) recreated with their original passwords.`);
3789:         } else if (landed.length) {
3790:           push({
3791:             step: "Migrate database users",
3792:             status: "copied",
3793:             detail: `${landed.length} of ${inv.mysqlAccounts.length} account(s) recreated; ${missing.map((m) => m.user).join(", ")} could not be reproduced (likely an auth plugin this engine does not support) — recreate ${missing.length === 1 ? "it" : "them"} and re-grant by hand`,
3794:           });
3795:         } else {
3796:           push({
3797:             step: "Migrate database users",
3798:             status: "failed",
3799:             detail: `none of the ${inv.mysqlAccounts.length} application database account(s) could be recreated${errCount ? ` (${errCount} statement error(s))` : ""}${ap.code !== 0 ? "" : ""} — apps that log in as their own DB user will get access-denied until they are created by hand`,
3800:           });
3801:         }
3802:       }
3803:     }
