3860:     // ---- 9a. Docker IMAGES -------------------------------------------------
3861:     // The migration used to copy files and named volumes but never the images, so
3862:     // standalone containers whose image was built locally (`studionexis/frontend:
3863:     // latest` — no registry host, exists nowhere but the old server) could never
3864:     // start on the new box. Every image any container references is made to exist
3865:     // here: pulled when it genuinely comes from a registry, otherwise streamed
3866:     // across with `docker save | gzip` → `gunzip | docker load`.
3867:     //
3868:     // This runs BEFORE compose up on purpose: with the images already present
3869:     // under the tags compose expects, `compose up` reuses them instead of
3870:     // rebuilding — which is both far more reliable and the difference between
3871:     // fitting on the disk and not.
3872:     const imagesNeeded: SrcImage[] = [];
3873:     if (plan.hasContainers && srcContainers.length) {
3874:       const seen = new Set<string>();
3875:       for (const c of srcContainers) {
3876:         if (!validImageRef(c.image) || seen.has(c.image)) continue;
3877:         seen.add(c.image);
3878:         const known = inv.images.find((i) => i.ref === c.image);
3879:         imagesNeeded.push({ ref: c.image, sizeBytes: known?.sizeBytes ?? 0, local: isLocalImageRef(c.image) });
3880:       }
