4961:     // ---- 12b. DOES THE SITE ACTUALLY SERVE? -------------------------------
4962:     // A listening port proves almost nothing: a real migration had the app up on
4963:     // 127.0.0.1:3720, the port open, and every request answered by the stock
4964:     // "Welcome to nginx" page — and a copied catch-all vhost happily answered 502
4965:     // for everything. So we make a REAL request for each hostname, with
4966:     // `curl --resolve` pinning it to this machine so the Host header and TLS SNI
4967:     // are the customer's actual domain. Anything 1xx–4xx means the vhost matched
4968:     // and something answered; 000 (nothing there) or 5xx does not.
4969:     //
4970:     // That was still not enough. On 2026-07-25 this check PASSED for a domain
4971:     // that was answering 200 with the Apache2 Debian Default Page, and for a
4972:     // domain that was being served a certificate belonging to a different site.
4973:     // So a 1xx–4xx is now necessary but not sufficient, and there are three more
4974:     // ways to fail:
4975:     //   - the body is a distribution placeholder or effectively empty
4976:     //     (defaultPageReason),
4977:     //   - the certificate this server presents for the name does not cover it
4978:     //     (servedCertNames — a browser shows a full-page security warning before
4979:     //     the visitor ever reaches the site),
4980:     //   - the name is simply not probed at all, because we never published it.
4981:     //
4982:     // And the LIST is now every hostname the SOURCE served, not the list we
4983:     // generated a config for. See the note on `sourceDomains`.
4984:     const siteProbes: { domain: string; http: string; https: string; serving: boolean; reason?: string }[] = [];
4985:     const publishedNames = [...new Set(servedSites.flatMap((s) => s.names))];
4986:     // Published names first (so the most important ones are inside the cap),
4987:     // then everything else the old server answered on.
4988:     const probeNames = [...new Set([...publishedNames, ...sourceDomains])].slice(0, 24);
4989:     const unprobed = [...new Set([...publishedNames, ...sourceDomains])].slice(24);
4990:     // Is anything at all listening on 443 here? Without that, https:// simply
4991:     // refuses the connection and there is no certificate to mismatch.
4992:     const tlsListening = await shOk(conn, `(ss -lnt 2>/dev/null || netstat -lnt 2>/dev/null) | grep -q ':443 '`);
4993:     if (probeNames.length) {
4994:       await report(
4995:         96,
4996:         "Verifying…",
4997:         `Making a real request to each of your ${probeNames.length} domain(s) to confirm the site actually answers — and checking what it answers WITH.`
4998:       );
4999:       for (const d of probeNames) {
5000:         const httpRes = await httpProbe(conn, `http://${d}/`, { domain: d, port: 80 });
5001:         const hasCert = await certExists(conn, d);
5002:         const httpsRes =
5003:           hasCert || tlsSecured.includes(d)
5004:             ? await httpProbe(conn, `https://${d}/`, { domain: d, port: 443 })
5005:             : { code: "", body: "" };
5006:         // With TLS present the HTTP block is a 301 to HTTPS, so HTTPS is the
5007:         // authoritative answer; without it, HTTP is.
5008:         const auth = httpsRes.code ? httpsRes : httpRes;
5009:         let serving = isServing(auth.code);
5010:         let reason = serving ? "" : auth.code === "000" ? "nothing answered at all" : `it answered ${auth.code}`;
5011: 
5012:         // (i) A 200 from a distribution placeholder is a dead site.
5013:         if (serving) {
5014:           const placeholder = defaultPageReason(auth.code, auth.body);
5015:           if (placeholder) {
5016:             serving = false;
5017:             reason = placeholder;
5018:           }
5019:         }
5020: 
5021:         // (ii) The certificate a browser would actually be shown. Checked
5022:         // whenever anything is listening on 443 — INCLUDING when we hold no
5023:         // certificate for this name, because that is precisely the case where
5024:         // another site's certificate gets served and the visitor is stopped by a
5025:         // security warning (studionexis.com was served nexis.revsports.ca's).
5026:         //
5027:         // Skipped when a CONTAINER owns 443: there the proxy issues its own
5028:         // certificates after DNS moves, so its placeholder self-signed cert
5029:         // today says nothing about tomorrow, and the HTTPS summary entry already
5030:         // explains that. The host is not the authority in that layout.
5031:         if (serving && tlsListening && webKind !== "container") {
5032:           const certNames = await servedCertNames(conn, d);
5033:           if (certNames && !certCoversName(certNames, d)) {
5034:             serving = false;
5035:             reason =
5036:               `this server answers https://${d}/ with a certificate issued for ${certNames.slice(0, 3).join(", ")}, which does not cover ${d} — ` +
5037:               `every visitor gets a full-page browser security warning before they reach the site`;
5038:           }
5039:         }
5040: 
5041:         siteProbes.push({ domain: d, http: httpRes.code, https: httpsRes.code, serving, reason });
5042:       }
5043:       const good = siteProbes.filter((p) => p.serving);
5044:       const bad = siteProbes.filter((p) => !p.serving);
5045:       for (const p of good) {
5046:         push({
5047:           step: `Site ${p.domain}`,
5048:           status: "running",
5049:           detail: p.https
5050:             ? `serving over HTTPS (HTTP ${p.http} → HTTPS ${p.https}) — point ${p.domain} at this server and it works`
5051:             : `serving over HTTP (${p.http}) — no certificate yet, so visitors get a browser warning on https:// until one is issued`,
5052:         });
5053:       }
5054:       for (const p of bad) {
5055:         push({
5056:           step: `Site ${p.domain} is NOT serving`,
5057:           status: "failed",
5058:           detail:
5059:             p.http === "000" && !p.https
5060:               ? `nothing answered for ${p.domain} on this server — the web server is not serving this name yet, so pointing DNS here would show an error`
5061:               : `${p.reason || `${p.domain} answered ${p.https || p.http}`} — the old server answered on this name, so it is not migrated until this one does too. Check \`docker logs\` / \`systemctl status\` for the app behind it, then reload the web server`,
5062:         });
5063:         // Only if we do not already hold a better-targeted reason for this name
5064:         // (the "could not publish" entry above knows exactly what was missing).
5065:         if (!blockers.some((b) => b.domain === p.domain)) {
5066:           blockers.push({
5067:             domain: p.domain,
5068:             why: p.reason || `it answered ${p.https || p.http} on the new server`,
5069:             fix: `make ${p.domain} serve here (start the app behind it, add or fix its vhost, and issue a certificate that covers ${p.domain}), then re-run the check`,
5070:           });
5071:         }
5072:       }
5073:       await report(
5074:         96,
5075:         "Verifying…",
5076:         `  serving: ${good.map((p) => p.domain).join(", ") || "none"}${bad.length ? `; NOT serving: ${bad.map((p) => p.domain).join(", ")}` : ""}.`
5077:       );
