5079:         push({
5080:           step: `${unprobed.length} more domain(s) were not checked`,
5081:           status: "copied",
5082:           detail: `${unprobed.slice(0, 8).join(", ")}${unprobed.length > 8 ? " …" : ""} — the old server also answered on these, but only the first ${probeNames.length} were probed. Check them by hand before moving DNS`,
5083:         });
5084:       }
5085:     }
5086:     // Independent of the per-domain probes above (which now also run in the
5087:     // containerised layout, because the source's domains have to answer there
5088:     // too): does the proxy container itself answer on port 80 at all?
5089:     if (webKind === "container") {
5090:       const code = await httpCode(conn, `http://127.0.0.1/`);
5091:       push({
5092:         step: "Site (containerised proxy)",
5093:         status: isServing(code) ? "running" : "failed",
5094:         detail: isServing(code)
5095:           ? `your proxy container answers on port 80 (HTTP ${code}) — point your DNS here and it serves`
5096:           : "nothing answered on port 80 — start your reverse-proxy container and check `docker logs`, or your domain will not resolve to anything",
5097:       });
5098:     }
