5100:     // ---- 13. Final honest summary ----------------------------------------
5101:     // THE SCORE. Denominator = every hostname the SOURCE served (sourceDomains),
5102:     // NOT the set we generated a config for. When the live inventory could not
5103:     // run we have no honest denominator and fall back to the probed set, saying
5104:     // so rather than quietly scoring ourselves against our own homework.
5105:     const servingNow = siteProbes.filter((p) => p.serving).map((p) => p.domain);
5106:     const servingSet = new Set(servingNow);
5107:     const probedSet = new Set(probeNames);
5108:     const scoredAgainst = sourceDomains.length ? sourceDomains : probeNames;
5109:     // Everything the old server served that this one does not. A name we did not
5110:     // get to probe counts here too — "we did not check" is not "it works" — but
5111:     // it is worded separately so the customer is never told a site is broken when
5112:     // what we actually mean is that we ran out of probe budget.
5113:     const unservedDomains = scoredAgainst.filter((d) => !servingSet.has(d));
5114:     const failedProbe = unservedDomains.filter((d) => probedSet.has(d));
5115:     const uncheckedDomains = unservedDomains.filter((d) => !probedSet.has(d));
