5122:         `${failedProbe.length} of the ${scoredAgainst.length} domain(s) the old server answered on ${failedProbe.length === 1 ? "does" : "do"} not serve here: ${failedProbe.slice(0, 8).join(", ")}${failedProbe.length > 8 ? " …" : ""}`
5123:       );
5124:     }
5125:     if (uncheckedDomains.length) {
5126:       outcomeReasons.push(
5127:         `${uncheckedDomains.length} domain(s) the old server answered on were not checked at all: ${uncheckedDomains.slice(0, 6).join(", ")}${uncheckedDomains.length > 6 ? " …" : ""}`
5128:       );
5129:     }
5130:     if (unitBlockers.length) {
5131:       outcomeReasons.push(
5132:         `${unitBlockers.length} migrated service(s) are not running: ${unitBlockers.slice(0, 5).map((b) => b.domain).join(", ")}${unitBlockers.length > 5 ? " …" : ""}`
5133:       );
5134:     }
5135:     if (!sourceDomains.length && probeNames.length) {
5136:       outcomeReasons.push(
5137:         "the old server's live configuration could not be read, so this score is measured against the sites we published rather than against everything the old server served — check the rest by hand"
5138:       );
5139:     }
5140:     const outcome: MigrationOutcome = outcomeReasons.length ? "COMPLETED_WITH_ISSUES" : "COMPLETED";
