2198: /**
2199:  * "Serving" means the web stack answered with an HTTP status — 200/301/401/404
2200:  * all prove the port is bound, the vhost matched and something is behind it.
2201:  * Only a connection failure (000) or a 5xx counts as not serving.
2202:  *
2203:  * This is necessary but NOT sufficient — see defaultPageReason and
2204:  * servedCertNames for the two ways a 200 still means a dead site.
2205:  */
2206: function isServing(code: string): boolean {
2207:   return /^[1-4]\d\d$/.test(code);
2208: }
