2211: // MIGRATED SYSTEMD UNITS — EXEC PRE-FLIGHT + HEALTH GATE
2212: // ===========================================================================
2213: /**
2214:  * A unit file is the one thing in a migration that is copied VERBATIM and then
2215:  * executed. Everything inside it — interpreter path, working directory, build
2216:  * artefacts — is a statement about the OLD machine, and none of it is checked
2217:  * before `systemctl enable --now` runs.
2218:  *
2219:  * Real incident, 2026-07-25 (and this had happened BEFORE — it is field note #13,
2220:  * documented after a previous migration and it recurred anyway, which is exactly
2221:  * why it is now an executable pre-flight instead of a paragraph in a document):
2222:  *
2223:  *     nexis-next.service
2224:  *       ExecStart=/usr/local/bin/node /opt/nexis/node_modules/next/dist/bin/next start -p 3105
2225:  *
2226:  * The source had a hand-installed Node at /usr/local/bin/node. The target has
2227:  * apt's Node 20 at /usr/bin/node and NOTHING at /usr/local/bin/node, so systemd
2228:  * failed the exec with status 203/EXEC. The unit crash-looped 78 times and the
2229:  * migration reported SUCCESS.
2230:  *
2231:  * So: before enabling anything, resolve the absolute executable of every
2232:  * ExecStart / ExecStartPre / ExecStartPost. Missing ⇒ symlink to the same binary
2233:  * found elsewhere on the target, else copy it from the source, else BLOCK and say
2234:  * exactly which unit wants exactly which path.
2235:  */
2236: type UnitExecRef = { directive: string; path: string };
2237: 
2238: /**
2239:  * Fold systemd's line continuations. A unit may legally spread one ExecStart over
2240:  * several lines with a trailing backslash, and reading it line-at-a-time would

2388: type UnitState = { active: string; sub: string; restarts: number };
2389: 
2390: /** One `systemctl show` read of the fields that decide "is this unit healthy". */
2391: async function unitState(conn: Client, unit: string): Promise<UnitState> {
2392:   if (!SVCNAME_RE.test(unit)) return { active: "unknown", sub: "", restarts: 0 };
2393:   const r = await sh(
2394:     conn,
2395:     `systemctl show ${unit}.service --property=ActiveState --property=SubState --property=NRestarts --no-pager 2>/dev/null`,
2396:     SETUP_TIMEOUT_MS
2397:   );
2398:   const out = clean(r.stdout, 512);
2399:   const pick = (k: string) => new RegExp(`${k}=([A-Za-z0-9-]*)`).exec(out)?.[1] ?? "";
2400:   const n = Number(pick("NRestarts"));
2401:   return { active: pick("ActiveState") || "unknown", sub: pick("SubState"), restarts: Number.isFinite(n) ? n : 0 };
2402: }
2403: 
2404: /** The last few journal lines for a unit, bounded — the ACTUAL error text. */
2405: async function unitJournal(conn: Client, unit: string, lines = 12): Promise<string> {
2406:   if (!SVCNAME_RE.test(unit)) return "";
2407:   const r = await sh(conn, `journalctl -u ${unit}.service -n ${lines} --no-pager -o cat 2>/dev/null`, SETUP_TIMEOUT_MS);
2408:   return probeBody(r.stdout, 2000);
2409: }
