2411: /**
2412:  * The recognisable "this was never built" failure. `/opt/nexis` came across with
2413:  * a `.next` directory that held a dev cache, not a production build, so even
2414:  * with the Node path fixed the unit exits 1 in a loop forever. Naming the fix
2415:  * (`next build`) is the difference between a customer fixing it in a minute and
2416:  * opening a ticket.
2417:  */
2418: const NEXT_NO_BUILD_RE = /Could not find a production build in the ['"`]?\.?\/?\.next['"`]?\s*directory/i;
2419: 
2420: /**
2421:  * AFTER enabling the migrated units, prove each one is actually up.
2422:  *
2423:  * `systemctl enable --now` returning 0 means "systemd accepted the job", not
2424:  * "the program runs" — and `is-active` sampled immediately after can read
2425:  * `activating` for a unit that is about to die, or even `active` in the window
2426:  * between a restart and the next crash. So we settle, then sample the restart
2427:  * counter TWICE: a unit whose NRestarts is climbing is crash-looping no matter
2428:  * what its state says at any instant. A service that has restarted 78 times must
2429:  * never be silent.
2430:  */
2431: async function unitHealthGate(opts: {
2432:   conn: Client;
2433:   units: string[];
2434:   say: (line: string) => Promise<void>;
2435: }): Promise<{ healthy: string[]; blockers: PendingItem[] }> {
2436:   const { conn, units, say } = opts;
2437:   const healthy: string[] = [];
2438:   const blockers: PendingItem[] = [];
2439:   const list = units.filter((u) => SVCNAME_RE.test(u)).slice(0, 30);
2440:   if (!list.length) return { healthy, blockers };
2441: 
2442:   await say(`  Waiting for ${list.length} migrated service(s) to settle before judging them.`);
2443:   await delay(12_000);
2444:   const first = new Map<string, UnitState>();
2445:   for (const u of list) first.set(u, await unitState(conn, u));
2446:   // A crash-loop needs a second look: RestartSec is typically 100ms–5s, so a
2447:   // 15-second window catches any unit that is cycling.
2448:   await delay(15_000);
2449: 
2450:   for (const u of list) {
2451:     const a = first.get(u) ?? { active: "unknown", sub: "", restarts: 0 };
2452:     const b = await unitState(conn, u);
2453:     const climbing = b.restarts > a.restarts;
2454:     const ok = b.active === "active" && !climbing;
2455:     if (ok) {
2456:       healthy.push(u);
2457:       continue;
2458:     }
2459: 
2460:     const journal = await unitJournal(conn, u);
2461:     const tail = journal.split("\n").filter((l) => l.trim()).slice(-4).join(" | ").slice(0, 400);
2462:     const state = climbing
2463:       ? `it is crash-looping — systemd has restarted it ${b.restarts} time(s) and the counter went up again while we watched`
2464:       : b.active === "failed"
2465:         ? `it is in the failed state (${b.sub || "failed"})`
2466:         : `it never became active (systemd reports ${b.active}${b.sub ? `/${b.sub}` : ""})`;
2467: 
2468:     if (NEXT_NO_BUILD_RE.test(journal)) {
2469:       blockers.push({
2470:         domain: `${u}.service`,
2471:         why:
2472:           `${state}. The application was copied across but was never BUILT here — Next.js reports ` +
2473:           `"Could not find a production build in the '.next' directory", so it exits immediately every time`,
2474:         fix: `run the production build in the app's directory, then start it: npm ci --omit=dev && npx next build && systemctl restart ${u}`,
2475:       });
2476:       await say(`  ${u}: not running — the app has no production build on this server (\`next build\` has never been run here).`);
2477:       continue;
2478:     }
2479: 
2480:     blockers.push({
2481:       domain: `${u}.service`,
2482:       why: `${state}${tail ? `. Its last log lines were: ${tail}` : ""}`,
2483:       fix: `systemctl status ${u} --no-pager -l; journalctl -u ${u} -n 50 --no-pager`,
2484:     });
2485:     await say(`  ${u}: NOT running — ${state}.`);
2486:   }
2487:   return { healthy, blockers };
2488: }
