2526:       stood.push(svc);
2527:       await say(
2528:         `  Disabled ${svc} on this server (it was ${wasEnabled || "installed"}${wasActive === "active" ? ", running" : ""}) — ` +
2529:           `${chosen === "apache" ? "Apache" : "nginx"} owns ports 80/443 here and two web servers cannot share them. To bring it back: systemctl unmask ${svc}.`
2530:       );
2531:     }
2532:   }
2533:   return stood;
2534: }
