613: /**
614:  * Idempotently ensure each allowlisted package is present on the target. Runs
615:  * `apt-get update` once, then for each key: skip if the check passes, else try
616:  * apt → dnf → yum with the FIXED package string. Returns which were newly
617:  * installed / already present / failed. Never throws (best-effort per package).
618:  *
619:  * `say` is optional so every existing call site keeps working unchanged; when it
620:  * is supplied the slow parts (metadata refresh + each install) narrate
621:  * themselves, because a package install is one of the three steps that can sit
622:  * silent for minutes (see withHeartbeat).
623:  */
624: async function ensurePackages(
625:   conn: Client,
626:   keys: PkgKey[],
627:   say?: (line: string) => Promise<void>
628: ): Promise<{ key: PkgKey; ok: boolean; already: boolean; err?: string }[]> {
629:   const beat = <T,>(what: string, run: () => Promise<T>): Promise<T> =>
630:     say ? withHeartbeat(what, say, run) : run();
631:   const out: { key: PkgKey; ok: boolean; already: boolean; err?: string }[] = [];
632:   if (keys.length === 0) return out;
633:   // `DEBIAN_FRONTEND=noninteractive` is NOT sufficient on Ubuntu 22.04+.
634:   // `needrestart` hooks dpkg's post-install phase and opens an interactive
635:   // "which services should be restarted?" prompt on a tty nobody is reading,
636:   // which wedges apt until INSTALL_TIMEOUT_MS expires.
637:   //
638:   // Seen live on a real migration (2026-07-25): installing certbot blocked on
639:   // /usr/lib/needrestart/dpkg-status for the FULL 10-minute timeout, which was
640:   // the entire HTTPS window — the run finished with soulpilates.com.vn and
641:   // srv1182755.hstgr.cloud still on plain HTTP. A hang here does not just cost
642:   // time, it silently costs certificates.
643:   //
644:   // NEEDRESTART_MODE=a answers that prompt automatically (restart what's needed);
645:   // NEEDRESTART_SUSPEND=1 disables the hook outright on versions that honour it.
646:   // The force-conf* options settle the OTHER classic apt prompt — "a config file
647:   // you modified has changed" — by keeping the existing file, which is the right
648:   // answer on a machine we are migrating INTO.
649:   const APT_ENV = "DEBIAN_FRONTEND=noninteractive NEEDRESTART_MODE=a NEEDRESTART_SUSPEND=1";
650:   const APT_OPTS = `-o Dpkg::Options::="--force-confdef" -o Dpkg::Options::="--force-confold"`;
651:   // Refresh apt metadata once (best-effort; ignored on non-apt systems). Also
652:   // finish any dpkg run a previous interrupted install left half-configured —
653:   // otherwise every later apt call inherits the wedge.
654:   await beat("finishing any half-configured package install", () =>
655:     execRemote(conn, `${APT_ENV} dpkg --configure -a >/dev/null 2>&1 || true`, INSTALL_TIMEOUT_MS).catch(() => ({ code: 0, stdout: "", stderr: "" }))
656:   );
657:   await beat("refreshing the package index (apt-get update)", () =>
658:     execRemote(conn, `${APT_ENV} apt-get update -y >/dev/null 2>&1 || true`, INSTALL_TIMEOUT_MS).catch(() => ({ code: 0, stdout: "", stderr: "" }))
659:   );
660:   for (const key of keys) {
661:     const already = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((r) => r.code === 0).catch(() => false);
662:     if (already) {
663:       out.push({ key, ok: true, already: true });
664:       continue;
665:     }
666:     // Docker is special-cased: install via the OFFICIAL convenience script — the
667:     // SAME method the platform's own provisioning uses (buildCloudInit in
668:     // worker/index.ts). The apt/dnf package list fails on Ubuntu because
669:     // `docker-compose-plugin` isn't in Ubuntu's default apt repo, so the whole
670:     // install returned non-zero and Docker never came up. get.docker.com adds
671:     // Docker's own repo and installs docker-ce + the compose plugin across
672:     // Debian/Ubuntu/RHEL. The command is a FIXED constant (no source input);
673:     // still best-effort + logged like every other package.
674:     const install =
675:       key === "docker"
676:         ? `curl -fsSL https://get.docker.com | sh && systemctl enable --now docker`
677:         : `${APT_ENV} apt-get install -y ${APT_OPTS} ${PKG_APT[key]} ` +
678:           `|| dnf install -y ${PKG_DNF[key]} ` +
679:           `|| yum install -y ${PKG_DNF[key]}`;
680:     const r = await beat(`installing ${PKG_LABEL[key]}`, () =>
681:       execRemote(conn, install, INSTALL_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }))
682:     );
683:     const nowPresent = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((x) => x.code === 0).catch(() => false);
684:     if (nowPresent) {
685:       out.push({ key, ok: true, already: false });
686:     } else {
687:       const tail = (r.stderr || r.stdout || "").split("\n").filter(Boolean).slice(-2).join(" ").slice(0, 200);
688:       out.push({ key, ok: false, already: false, err: tail || `install exit ${r.code}` });
689:     }
690:   }
691:   return out;
692: }
