714:   const dockerVolumes = [...new Set(items.dockerVolumes ?? [])].filter((v) => VOLNAME_RE.test(v)).slice(0, 60);
715:   const composeDirs = [...new Set(items.composeDirs ?? [])].filter((p) => validPath(p)).slice(0, 40);
716:   const verifyPorts = [...new Set((items.verifyPorts ?? []).filter((p) => Number.isInteger(p) && p >= 1 && p <= 65535 && p !== 22))].slice(0, 60);
717:   const hasContainers = !!items.hasContainers || (scan.containers?.length ?? 0) > 0 || composeDirs.length > 0 || dockerVolumes.length > 0;
718:   const webServers = [...new Set(items.webServers ?? [])].filter((w): w is "nginx" | "apache" => w === "nginx" || w === "apache");
719:   const runtimes = [...new Set(items.runtimes ?? [])].filter((r): r is "nodejs" | "python3" => r === "nodejs" || r === "python3");
720:   const services = [...new Set((scan.services ?? []).map((s) => s?.name ?? "").filter((n) => SVCNAME_RE.test(n)))].slice(0, 30);
