724:       image: String(c?.image ?? ""),
725:       ports: String(c?.ports ?? ""),
726:       mounts: Array.isArray(c?.mounts) ? c!.mounts!.map((m) => String(m)) : [],
727:     }))
728:     .slice(0, 30);
