730:   const prereqs: PkgKey[] = [];
731:   // Install the engine variant that MATCHES the source (Oracle MySQL vs MariaDB).
732:   if (dbEngines.includes("mysql")) prereqs.push(mysqlVariant === "mysql" ? "mysql_oracle" : "mysql");
